import React from 'react';
import ReactDOM from 'react-dom/client';
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';

const WF_PROB = ['Aguardando RCA','Aguardando Aprovacao Lider de Torre','Aguardando Aprovacao Ger. Problema','Solucao Rejeitada','Aguardando Planejamento','Aguardando Execucao','Em Execucao','Aguardando Demanda/Projeto','Em Monitoramento','Fechado','Cancelado','RCA em Desenvolvimento','Aguardando Aprovacao Tecnica RCA','Aguardando Aprovacao Governanca RCA','Resolvido','Em Planejamento','Aguardando Aprovacao Tecnica','Aguardando Aprovacao Governanca','Aguardando Demanda'];

const PAGE_W = 1500;
const TIX_W  = 280;
const SQ_W   = 60;
const PR_W   = 50;
const NI_W   = 90;
const ST_W   = 110;
const FT_W   = 70;
const DIH_W  = 70;
const DH_W   = 70;
const DC_W   = 70;
const IMP_W  = 18;
const TV_W   = 80;   // Ticket Vinculado key
const TVI_W  = 20;   // Impedimento do TV (icon)
const TVS_W  = 100;  // Status do TV
const TVP_W  = 90;   // Pacote do TV
const ROW_H  = 22;
const CB     = '1px solid #e2e8f0';
const PAGE_H = Math.round((210 / 297) * PAGE_W);
const cellBase = { flexShrink: 0, height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', borderRight: CB, overflow: 'hidden' };
const NTT_LOGO_URL  = 'data:image/png;base64,';
const CPFL_LOGO_URL = 'data:image/png;base64,';

function sc(s) {
  const l = String(s||'').toLowerCase();
  if (l.includes('fechad')||l.includes('resolv')||l.includes('cancelad')) return '#16a34a';
  if (l.includes('execu')||l.includes('monitoramento')) return '#2563eb';
  if (l.includes('rca')||l.includes('aprovac')) return '#7c3aed';
  if (l.includes('aguard')||l.includes('planejam')) return '#d97706';
  if (l.includes('rejeit')) return '#dc2626';
  return '#6b7280';
}
function pb(v) {
  const p = String(v||'').toLowerCase().trim();
  if (p.includes('crise')||p.includes('critica')) return 'Crise';
  if (p==='alto'||p==='alta') return 'Alto';
  if (p.includes('medio')||p.includes('media')) return 'Médio';
  if (p==='baixo'||p==='baixa') return 'Baixo';
  if (p==='muito baixo') return 'M.Baixo';
  return null;
}
function fd(v) {
  if (!v) return '';
  const m = String(v).trim().match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? m[3]+'/'+m[2]+'/'+m[1] : '';
}
function sqd(t) {
  if (t.squadPrincipal) return t.squadPrincipal;
  if (t._resolvedSquad) return t._resolvedSquad;
  return (t.grupoSuporte||'').replace(/^\d+\s*-\s*/,'').trim();
}
function tr(s, n) { const x=String(s||''); return x.length>n?x.slice(0,n-1)+'\u2026':x; }

function hC(w, l, s) {
  return (
    <div style={{ ...cellBase, width:w, flexDirection:'column', justifyContent:'flex-end', padding:'3px 2px', background:'#f1f5f9', gap:0 }}>
      <span style={{ fontSize:7.5, fontWeight:800, color:'#475569', letterSpacing:'0.04em', textTransform:'uppercase', textAlign:'center', lineHeight:1.2 }}>{l}</span>
      {s && <span style={{ fontSize:6.5, color:'#94a3b8', textAlign:'center', lineHeight:1 }}>{s}</span>}
    </div>
  );
}

function PRow({ ticket, rowBg, ticketMap }) {
  const squad = tr(sqd(ticket), 10);
  const status = tr(ticket.status||'', 20);
  const col = sc(ticket.status);
  const prio = pb(ticket.prioridadeInterna);
  const isImp = ticket.impedimento === true;
  const motivo = tr(ticket.observacaoAdicional || ticket.motivoImpedimento || ticket.observacao || '', 90);
  const bg = rowBg || (isImp ? '#fff1f2' : '#ffffff');

  // Linked ticket lookup
  const tvKey = (() => {
    const v = ticket.ticketsVinculados;
    if (!v) return null;
    const keys = String(v).split(',').map(k => k.trim()).filter(Boolean);
    return keys[0] || null;
  })();
  const tvTicket = tvKey && ticketMap ? ticketMap.get(tvKey) : null;
  const tvStatus = tvTicket ? tr(tvTicket.status||'', 18) : '';
  const tvStatusCol = tvTicket ? sc(tvTicket.status) : '#6b7280';
  const tvImp = tvTicket ? tvTicket.impedimento === true : false;
  const tvPacote = tvTicket ? tr(tvTicket.pacote||'', 14) : '';

  return (
    <div style={{ display:'flex', alignItems:'flex-start', minHeight:ROW_H, borderBottom:'1px solid #e2e8f0', background:bg }}>
      <div style={{ ...cellBase, width:TIX_W, gap:3, padding:'0 5px', justifyContent:'flex-start' }}>
        <div style={{ background:'#dc2626', color:'#fff', fontSize:7, fontWeight:800, padding:'1px 3px', borderRadius:3, flexShrink:0, minWidth:28, textAlign:'center' }}>PROB</div>
        {isImp && <span style={{ fontSize:8, flexShrink:0 }}>⚠</span>}
        <span style={{ fontSize:7.5, fontWeight:700, color:isImp?'#dc2626':'#1d4ed8', fontFamily:'monospace', flexShrink:0 }}>{ticket.issueKey||ticket.id||''}</span>
        <span style={{ fontSize:7.5, color:isImp?'#b91c1c':'#374151', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap', flex:1 }}>{ticket.summary||''}</span>
      </div>
      <div style={{ ...cellBase, width:SQ_W, padding:'0 2px' }}>
        {squad && <span style={{ fontSize:7, fontWeight:600, color:'#065f46', background:'#d1fae5', padding:'1px 3px', borderRadius:3, maxWidth:SQ_W-6, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{squad}</span>}
      </div>
      <div style={{ ...cellBase, width:PR_W, padding:'0 2px' }}>
        {prio && <span style={{ fontSize:7, fontWeight:600, color:'#374151', whiteSpace:'nowrap' }}>{prio}</span>}
      </div>
      <div style={{ ...cellBase, width:NI_W, padding:'0 3px' }}>
        <span style={{ fontSize:6.5, color:'#374151', textAlign:'center', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap', maxWidth:NI_W-6 }}>{tr(ticket.naturezaIniciativa||ticket.naturezaOperacao||'',22)}</span>
      </div>
      <div style={{ ...cellBase, width:ST_W, padding:'0 2px' }}>
        <span style={{ fontSize:7, fontWeight:600, color:col, maxWidth:ST_W-4, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap', textAlign:'center' }}>{status}</span>
      </div>
      <div style={{ ...cellBase, width:FT_W, padding:'0 2px' }}>
        <span style={{ fontSize:7.5, color:'#374151', textAlign:'center' }}>{fd(ticket.dataFimTesteInterno)||'—'}</span>
      </div>
      <div style={{ ...cellBase, width:DIH_W, padding:'0 2px' }}>
        <span style={{ fontSize:7.5, color:'#374151', textAlign:'center' }}>{fd(ticket.dataInicioHomologacao||ticket.dataInicioHomologacaoEfetiva||ticket.dataInicioHomologacaoPlanejada)||'—'}</span>
      </div>
      <div style={{ ...cellBase, width:DH_W, padding:'0 2px' }}>
        <span style={{ fontSize:7.5, color:'#374151', textAlign:'center' }}>{fd(ticket.dataFimHomologacao)||'—'}</span>
      </div>
      <div style={{ ...cellBase, width:DC_W, padding:'0 2px' }}>
        <span style={{ fontSize:7.5, color:ticket.dataConclusao?'#16a34a':'#374151', textAlign:'center', fontWeight:ticket.dataConclusao?700:400 }}>{fd(ticket.dataConclusao)||'—'}</span>
      </div>
      <div style={{ ...cellBase, width:IMP_W }}>{isImp && <span style={{ fontSize:11 }}>⚠</span>}</div>
      {/* Linked ticket columns */}
      <div style={{ ...cellBase, width:TV_W, padding:'0 2px' }}>
        {tvKey && <span style={{ fontSize:7, fontWeight:700, color:'#374151', fontFamily:'monospace', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{tvKey}</span>}
      </div>
      <div style={{ ...cellBase, width:TVI_W }}>
        {tvImp && <span style={{ fontSize:11 }}>⚠</span>}
      </div>
      <div style={{ ...cellBase, width:TVS_W, padding:'0 2px' }}>
        {tvStatus && <span style={{ fontSize:6.5, fontWeight:600, color:tvStatusCol, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap', textAlign:'center', maxWidth:TVS_W-4 }}>{tvStatus}</span>}
      </div>
      <div style={{ ...cellBase, width:TVP_W, padding:'0 2px' }}>
        {tvPacote && <span style={{ fontSize:6.5, fontWeight:600, color:'#374151', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap', maxWidth:TVP_W-4 }}>{tvPacote}</span>}
      </div>
      <div style={{ flex:1, minHeight:'100%', display:'flex', alignItems:'flex-start', padding:'2px 6px', overflow:'hidden' }}>
        <span style={{ fontSize:7.5, color:isImp?'#7f1d1d':'#6b7280', lineHeight:1.25, whiteSpace:'normal', wordBreak:'break-word' }}>{motivo}</span>
      </div>
    </div>
  );
}

function ColHdr() {
  return (
    <div style={{ display:'flex', borderBottom:'2px solid #cbd5e1', minHeight:36, background:'#f1f5f9' }}>
      {hC(TIX_W,'Ticket',null)}
      {hC(SQ_W,'Squad',null)}
      {hC(PR_W,'Prio',null)}
      {hC(NI_W,'Nat.','Iniciativa')}
      {hC(ST_W,'Status',null)}
      {hC(FT_W,'Fim Teste','Interno')}
      {hC(DIH_W,'Ini','Homolog')}
      {hC(DH_W,'Fim','Homolog')}
      {hC(DC_W,'Data','Conclusão')}
      {hC(IMP_W,'⚠','Imp')}
      {hC(TV_W,'Ticket','Vinculado')}
      {hC(TVI_W,'⚠','TV')}
      {hC(TVS_W,'Status','TV')}
      {hC(TVP_W,'Pacote','TV')}
      <div style={{ flex:1, display:'flex', alignItems:'flex-end', padding:'3px 6px' }}>
        <span style={{ fontSize:7.5, fontWeight:800, color:'#475569', letterSpacing:'0.04em', textTransform:'uppercase', lineHeight:1.2 }}>Motivo / Observação</span>
      </div>
    </div>
  );
}

function Stats({ tickets }) {
  const total = tickets.length;
  const imped = tickets.filter(t => t.impedimento === true).length;
  const stMap = {}; tickets.forEach(t => { if (t.status) stMap[t.status]=(stMap[t.status]||0)+1; });
  const wfIdx = {}; WF_PROB.forEach((s,i) => { wfIdx[s]=i; });
  const topSt = Object.entries(stMap).sort((a,b) => { const ia=wfIdx[a[0]]??WF_PROB.length; const ib=wfIdx[b[0]]??WF_PROB.length; return ia!==ib?ia-ib:b[1]-a[1]; }).slice(0,10);
  const sqMap = {}; tickets.forEach(t => { const s=tr(sqd(t)||'Sem squad',10); sqMap[s]=(sqMap[s]||0)+1; });
  const topSq = Object.entries(sqMap).sort((a,b) => b[1]-a[1]).slice(0,8);
  const H=54;
  const bx=(bg,fw)=>({ background:bg,borderRadius:5,padding:'4px 7px',display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',minWidth:fw,height:H });
  const nm=(c,fs)=>({ fontSize:fs,fontWeight:900,color:c,lineHeight:1 });
  const lb=(c)=>({ fontSize:6.5,fontWeight:700,color:c,marginTop:2,textTransform:'uppercase',letterSpacing:'0.04em',textAlign:'center',maxWidth:70,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap' });
  const dv={ width:1,background:'#cbd5e1',alignSelf:'stretch',margin:'0 8px' };
  return (
    <div style={{ background:'#f8fafc',borderBottom:'2px solid #cbd5e1',padding:'8px 12px',display:'flex',alignItems:'stretch' }}>
      <div style={{ display:'flex',flexDirection:'column' }}>
        <div style={{ fontSize:7,fontWeight:800,color:'#64748b',textTransform:'uppercase',letterSpacing:'0.06em',marginBottom:3 }}>Totais</div>
        <div style={{ display:'flex',gap:5 }}>
          <div style={bx('#dc2626',60)}><span style={nm('#fff',26)}>{total}</span><span style={lb('#fca5a5')}>Problemas</span></div>
          <div style={bx(imped>0?'#991b1b':'#374151',60)}><span style={nm('#fff',26)}>{imped}</span><span style={lb(imped>0?'#fca5a5':'#9ca3af')}>Impedidos</span></div>
        </div>
      </div>
      <div style={dv}/>
      <div style={{ display:'flex',flexDirection:'column' }}>
        <div style={{ fontSize:7,fontWeight:800,color:'#64748b',textTransform:'uppercase',letterSpacing:'0.06em',marginBottom:3 }}>Por Status</div>
        <div style={{ display:'flex',gap:5,flexWrap:'wrap',alignItems:'flex-start' }}>
          {topSt.map(([s,c]) => { const col=sc(s); return (
            <div key={s} style={{ ...bx(col+'1a',60), border:'1px solid '+col+'55' }}>
              <span style={nm(col,22)}>{c}</span>
              <span style={{ fontSize:6.5,fontWeight:700,color:col,marginTop:2,textAlign:'center',lineHeight:1.2,maxWidth:70,whiteSpace:'normal',wordBreak:'break-word' }}>{tr(s,16)}</span>
            </div>
          );})}
        </div>
      </div>
      <div style={dv}/>
      <div style={{ display:'flex',flexDirection:'column' }}>
        <div style={{ fontSize:7,fontWeight:800,color:'#64748b',textTransform:'uppercase',letterSpacing:'0.06em',marginBottom:3 }}>Por Squad</div>
        <div style={{ display:'flex',gap:5,flexWrap:'wrap',alignItems:'flex-start' }}>
          {topSq.map(([s,c]) => (
            <div key={s} style={{ ...bx('#d1fae5',60), border:'1px solid #059669' }}>
              <span style={nm('#065f46',22)}>{c}</span>
              <span style={{ fontSize:6.5,fontWeight:700,color:'#065f46',marginTop:2,textAlign:'center',lineHeight:1.2,maxWidth:70,whiteSpace:'normal',wordBreak:'break-word' }}>{tr(s,12)}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function GroupedContent({ groups, tickets, exportedAt, ticketMap }) {
  return (
    <div style={{ width:PAGE_W, background:'#fff', color:'#111827', fontFamily:'Inter,Segoe UI,Arial,sans-serif', fontSize:10 }}>
      <div style={{ display:'flex',alignItems:'center',justifyContent:'space-between',padding:'8px 12px 6px',borderBottom:'2px solid #dc2626',background:'#f8fafc' }}>
        <div>
          <div style={{ fontSize:14,fontWeight:800,color:'#7f1d1d',letterSpacing:'-0.01em' }}>Gestão de Problemas</div>
          <div style={{ fontSize:8,color:'#6b7280',marginTop:1 }}>Exportado em {exportedAt} · {tickets.length} problema{tickets.length!==1?'s':''}</div>
        </div>
      </div>
      <Stats tickets={tickets} />
      <ColHdr />
      {groups.map((g, gi) => (
        <div key={g.key}>
          <div style={{ display:'flex',alignItems:'center',background:'#fee2e2',borderBottom:'1px solid #fca5a5',borderTop:gi>0?'2px solid #f87171':'none',minHeight:24,padding:'0 6px' }}>
            <span style={{ fontSize:9.5,fontWeight:800,color:'#991b1b',textTransform:'uppercase',letterSpacing:'0.04em' }}>{g.label}</span>
            <span style={{ fontSize:8.5,color:'#dc2626',marginLeft:8 }}>({g.tickets.length})</span>
          </div>
          {g.tickets.map((t,ti) => (
            <PRow key={t.issueKey||t.id||ti} ticket={t} rowBg={ti%2===0?'#ffffff':'#f8fafc'} ticketMap={ticketMap} />
          ))}
        </div>
      ))}
      <div style={{ padding:'8px 12px 10px',borderTop:'3px solid #dc2626',background:'#f8fafc',marginTop:4 }}>
        <span style={{ fontSize:7,color:'#9ca3af' }}>SGT — Gestão de Problemas</span>
      </div>
    </div>
  );
}

function CoverPage({ exportedAt, nttUrl, cpflUrl }) {
  const dateStr = new Date().toLocaleDateString('pt-BR', { day:'numeric', month:'long', year:'numeric' });
  return (
    <div style={{ width:PAGE_W, height:PAGE_H, position:'relative', fontFamily:'Inter,Segoe UI,Arial,sans-serif', overflow:'hidden', background:'linear-gradient(135deg, #450a0a 0%, #7f1d1d 45%, #3b0d0d 100%)' }}>
      <div style={{ position:'absolute', top:40, left:48, zIndex:10 }}>
        {nttUrl && <img src={nttUrl} style={{ height:44, objectFit:'contain' }} />}
      </div>
      <div style={{ position:'absolute', top:32, right:52, zIndex:10 }}>
        {cpflUrl && <img src={cpflUrl} style={{ height:60, objectFit:'contain' }} />}
      </div>
      <div style={{ position:'absolute', top:118, left:48, right:48, height:2, background:'rgba(255,255,255,0.22)' }} />
      <div style={{ position:'absolute', bottom:180, left:52 }}>
        <div style={{ fontSize:72, fontWeight:300, color:'#ffffff', lineHeight:1.1, letterSpacing:'-0.01em' }}>Gestão de Problemas</div>
        <div style={{ fontSize:28, fontWeight:400, color:'#fca5a5', marginTop:18, letterSpacing:'0.01em' }}>Status Report Operacional — Semanal</div>
        <div style={{ fontSize:20, fontWeight:300, color:'#f87171', marginTop:14 }}>{dateStr}</div>
      </div>
      <div style={{ position:'absolute', bottom:30, left:52, fontSize:13, color:'#7f1d1d' }}>© 2026 NTT DATA, Inc.</div>
      <div style={{ position:'absolute', bottom:30, right:52, fontSize:12, color:'#991b1b' }}>SGT · {exportedAt}</div>
    </div>
  );
}

export async function exportProblemsPdf({ filteredTickets = [], activeTab = 'workflow', escopoFilter }) {
  const exportedAt = new Date().toLocaleString('pt-BR', { day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit' });

  // Filter to PROBLEMAS only
  const tickets = filteredTickets.filter(t => {
    const e = String(t.escopo||'').trim().toUpperCase().replace(/\s+/g,' ');
    return e === 'PROBLEMAS' || e === 'PROBLEMA';
  });

  // Group by workflow status
  const wfIdx = {}; WF_PROB.forEach((s,i) => { wfIdx[s]=i; });
  const map = new Map();
  tickets.forEach(t => { const s=t.status||'(sem status)'; if(!map.has(s))map.set(s,[]); map.get(s).push(t); });
  const groups = [...map.entries()]
    .sort(([a],[b]) => { const ia=wfIdx[a]??WF_PROB.length; const ib=wfIdx[b]??WF_PROB.length; return ia!==ib?ia-ib:a.localeCompare(b,'pt-BR'); })
    .map(([label,tks]) => ({ key:label, label, tickets:tks }));

  const A4_W = 297;
  const A4_H = 210;
  const pdf = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  const SCALE = 1.5;

  async function renderPage(component) {
    const el = document.createElement('div');
    el.style.cssText = `position:fixed;left:-9999px;top:0;width:${PAGE_W}px;background:transparent;z-index:-9999;pointer-events:none;`;
    document.body.appendChild(el);
    const r = ReactDOM.createRoot(el);
    r.render(component);
    await new Promise(res => setTimeout(res, 800));
    const imgs = Array.from(el.querySelectorAll('img'));
    await Promise.all(imgs.map(img => img.complete ? Promise.resolve() : new Promise(res => { img.onload = res; img.onerror = res; })));
    try {
      return await html2canvas(el, { scale: SCALE, useCORS: true, allowTaint: true, backgroundColor: null, logging: false, width: PAGE_W });
    } finally { r.unmount(); document.body.removeChild(el); }
  }

  try {
    // Cover
    const coverCanvas = await renderPage(<CoverPage exportedAt={exportedAt} nttUrl={NTT_LOGO_URL} cpflUrl={CPFL_LOGO_URL} />);
    const coverImg = coverCanvas.toDataURL('image/png');
    pdf.addImage(coverImg, 'PNG', 0, 0, A4_W, Math.min((coverCanvas.height/coverCanvas.width)*A4_W, A4_H));

    // Content
    const contentEl = document.createElement('div');
    contentEl.style.cssText = `position:fixed;left:-9999px;top:0;width:${PAGE_W}px;background:#fff;z-index:-9999;pointer-events:none;`;
    document.body.appendChild(contentEl);
    const contentRoot = ReactDOM.createRoot(contentEl);
    const ticketMap = new Map(filteredTickets.map(t => [t.issueKey||t.id, t]));
    contentRoot.render(<GroupedContent groups={groups} tickets={tickets} exportedAt={exportedAt} ticketMap={ticketMap} />);
    await new Promise(r => setTimeout(r, 700));
    try {
      const canvas = await html2canvas(contentEl, { scale: SCALE, useCORS: true, backgroundColor: '#fff', logging: false, width: PAGE_W });
      const pageHeightPx = (A4_H / A4_W) * canvas.width;
      let yOffset = 0;
      while (yOffset < canvas.height) {
        pdf.addPage();
        const sliceH = Math.min(pageHeightPx, canvas.height - yOffset);
        const pageCanvas = document.createElement('canvas');
        pageCanvas.width = canvas.width; pageCanvas.height = sliceH;
        const ctx = pageCanvas.getContext('2d');
        ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, pageCanvas.width, pageCanvas.height);
        ctx.drawImage(canvas, 0, -yOffset);
        const imgData = pageCanvas.toDataURL('image/jpeg', 0.82);
        pdf.addImage(imgData, 'JPEG', 0, 0, A4_W, (sliceH/canvas.width)*A4_W);
        yOffset += sliceH;
      }
    } finally { contentRoot.unmount(); document.body.removeChild(contentEl); }

    const dateStr = new Date().toISOString().slice(0, 10);
    pdf.save('gestao-problemas-' + dateStr + '.pdf');
  } catch (e) {
    console.error('[exportProblemsPdf]', e);
    throw e;
  }
}
